python3 -c "
import numpy as np
lines=open('complex_opt.xyz').read().splitlines()
n=int(lines[0]); print('atoms:',n, '| comment:', lines[1])
atoms=[]
for ln in lines[2:2+n]:
    p=ln.split(); atoms.append((p[0], np.array([float(p[1]),float(p[2]),float(p[3])])))
cr=atoms[0][1]
ns=[(i,el,np.linalg.norm(p-cr)) for i,(el,p) in enumerate(atoms) if el=='N']
print('Cr-N distances:')
for i,el,d in ns: print(f'  N idx {i}: {d:.3f} A')
sis=[(i,el,np.linalg.norm(p-cr)) for i,(el,p) in enumerate(atoms) if el=='Si']
print('Si atoms:', [(i,round(d,3)) for i,el,d in sis])
# N-Si distances
for i,(el,p) in enumerate(atoms):
    if el=='Si':
        for j,(el2,q) in enumerate(atoms):
            if el2=='N':
                d=np.linalg.norm(p-q)
                if d<2.0: print(f'N-Si bond: N{j}-Si{i} = {d:.3f}')
"
